// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from address and an address to act as caddress; we also fuzz an uint v
    // The property: for ANY inputs where _tos is an empty array, the reference contract MUST revert;
    // the mutant that uses `require(_tos.length >= 0)` will NOT revert and thus differs.
    function testFuzz_property(address from, address caddress, uint256 v) public {
        // keep addresses wide but avoid the zero-address for clarity (not required):
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));

        // build an empty _tos array to exercise the boundary
        address[] memory tos = new address[](0);

        // Call transfer and record whether it completes (true) or reverts (false).
        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference C MUST revert for empty _tos, so ok must be false.
        // This will pass on the reference and fail on the mutant that changed the require to `_tos.length >= 0`.
        assertTrue(!ok);
    }
}
